// ── Demonstrating cache effects through access patterns ─────────
// Run with Node. Absolute numbers vary by machine; the RATIOS are the point.

const SIZE = 16 * 1024 * 1024;          // 16M ints = 64 MB — bigger than most L3 caches
const arr = new Int32Array(SIZE);
for (let i = 0; i < SIZE; i++) arr[i] = i;

const LINES = SIZE / 16;                // 64-byte line = 16 ints → 1M lines

// SEQUENTIAL: arr[0], arr[1], arr[2] ... — 1 miss per line, then 15 cheap hits,
// and the hardware prefetcher streams the next lines in ahead of time
function sumSequential() {
  let sum = 0;
  for (let i = 0; i < SIZE; i++) sum += arr[i];
  return sum;
}

// STRIDE-16: arr[0], arr[16], arr[32] ... — one int per 64-byte line.
// Every read touches a new line, but the pattern is regular, so the
// hardware prefetcher still fetches lines ahead of time.
function sumStride16() {
  let sum = 0;
  for (let i = 0; i < SIZE; i += 16) sum += arr[i];
  return sum;
}

// RANDOM LINES: the same 1M one-int-per-line accesses as stride-16,
// but in shuffled order — the prefetcher cannot guess what comes next
const order = new Int32Array(LINES);
for (let i = 0; i < LINES; i++) order[i] = i;
for (let i = LINES - 1; i > 0; i--) {   // Fisher-Yates shuffle (unbiased)
  const j = Math.floor(Math.random() * (i + 1));
  [order[i], order[j]] = [order[j], order[i]];
}
function sumRandom() {
  let sum = 0;
  for (let k = 0; k < LINES; k++) sum += arr[order[k] * 16];
  return sum;
}

// Report the cost PER READ so the three loops are comparable
const nsPerRead = (fn, reads) => {
  fn();                                  // warm-up run (JIT + caches)
  const s = performance.now();
  fn();
  return ((performance.now() - s) * 1e6 / reads).toFixed(2);
};
console.log('Sequential ns/read:', nsPerRead(sumSequential, SIZE));  // ~1 ns
console.log('Stride-16  ns/read:', nsPerRead(sumStride16, LINES));   // similar — prefetcher keeps up
console.log('Random     ns/read:', nsPerRead(sumRandom, LINES));     // several times slower

