// ── Measuring the hierarchy: latency per load vs working-set size (Node.js) ──
// Pointer chasing: each load's address comes from the previous load, so the CPU
// cannot prefetch or overlap misses — we see raw latency of whichever level holds the data.

const { performance } = require('node:perf_hooks');

// One random cycle through all n slots (Sattolo's algorithm)
function buildCycle(n) {
  const next = new Int32Array(n);
  for (let i = 0; i < n; i++) next[i] = i;
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * i); // j < i guarantees a single cycle
    [next[i], next[j]] = [next[j], next[i]];
  }
  return next;
}

function nsPerLoad(bytes, steps = 20_000_000) {
  const next = buildCycle(bytes / 4);
  let p = 0;
  for (let i = 0; i < 1_000_000; i++) p = next[p];  // warm up caches + JIT
  const t0 = performance.now();
  for (let i = 0; i < steps; i++) p = next[p];      // dependent loads
  return { ns: ((performance.now() - t0) * 1e6) / steps, p };
}

console.log('working set | ns per load');
for (const kb of [16, 512, 8 * 1024, 64 * 1024, 512 * 1024]) {
  const { ns, p } = nsPerLoad(kb * 1024);
  console.log(`${String(kb).padStart(8)} KB | ${ns.toFixed(1)}${p < 0 ? '!' : ''}`);
}

// Typical shape (Apple M1 Pro; x86 looks similar; timings are noisy, run twice):
//      16 KB |     ~3  (L1 hit + JS loop overhead)
//     512 KB |   ~5-10 (L2)
//    8192 KB |  ~20-60 (L3 / system-level cache)
//   65536 KB | ~100-350 (DRAM)
//  524288 KB | ~150-400 (DRAM + TLB misses)
// Each step down the hierarchy multiplies the cost of a dependent load.
